using HospitalityOS.SharedKernel.Collections;
using HospitalityOS.SharedKernel.Pricing;

namespace HospitalityOS.Domain.Dining.Menus;

/// <summary>
/// A dish or drink on a <see cref="Menu"/> (Journey 3). Holds no POS-vendor fields.
/// </summary>
/// <param name="Id">Stable ID, generated by the caller through <c>IIdGenerator</c> when the item is added.</param>
/// <param name="Name">Display name, e.g. <c>Wild mushroom risotto</c>; required.</param>
/// <param name="Description">What it is; optional.</param>
/// <param name="Price">Price; <c>null</c> when not published, so the AI says it does not know rather than guessing.</param>
/// <param name="Category">Section of the menu, e.g. <c>Mains</c>; optional.</param>
/// <param name="Dietary">Dietary tags; normalized (sorted, de-duplicated, vegan implies vegetarian).</param>
/// <param name="IsAvailable">Whether it can currently be ordered. The AI does not claim real-time availability beyond this flag.</param>
public sealed record MenuItem(
    MenuItemId Id,
    string Name,
    string? Description = null,
    Money? Price = null,
    string? Category = null,
    ValueList<DietaryTag>? Dietary = null,
    bool IsAvailable = true)
{
    /// <summary>
    /// Whether the item has every tag in <paramref name="required"/>.
    /// </summary>
    public bool Has(IEnumerable<DietaryTag> required) => required.All(tag => Dietary?.Contains(tag) == true);
}
